import React from 'react';

const Requests = () => {
  return (
    <div className="container mx-auto px-4 py-8">
      <h1 className="text-3xl font-bold mb-6">Tenant Requests</h1>
      <div className="text-center py-12">
        <p className="text-gray-600 text-lg">Tenant requests will be displayed here.</p>
        <p className="text-gray-500 mt-2">This will show all active apartment requests from tenants.</p>
      </div>
    </div>
  );
};

export default Requests;
